#!/usr/bin/env bash
# Fixed-code timing. Requires >=2 effective CPUs; uses one CPU worker; no dataset/training changes.
set -u
if [ "$#" -ne 1 ] || [ "$1" != "--authorize-cachetiming-once" ]; then
  printf '%s\n' '用法：bash /root/autodl-tmp/run_dual_cachetiming.sh --authorize-cachetiming-once' >&2
  exit 2
fi
DATA=/root/autodl-tmp
if [ ! -d "$DATA" ]; then printf '%s\n' "HOLD：数据盘不存在：$DATA" >&2; exit 2; fi
LOG=$(mktemp "$DATA/run_dual_cachetiming.XXXXXX.log") || exit 2
printf '%s\n' '资源：HIGH-CPU，至少2有效CPU、2GiB可用内存、1GiB空闲数据盘；单进程单线程，不用GPU。8次预热+32次计时搜索；算法不改，不采集、不训练。'
printf 'LAUNCHER_LOG=%s\n' "$LOG"
printf '%s\n' '前台短任务；完成后自动打包。请勿重复启动。'
(
  set -e
  cd /root/MineSim-Dynamic
  source /root/miniconda3/etc/profile.d/conda.sh 2>/dev/null || true
  conda activate minesim
  export PYTHONPATH=/root/MineSim-Dynamic
  export PYTHONDONTWRITEBYTECODE=1
  export CUDA_VISIBLE_DEVICES=""
  export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
  export NUMEXPR_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
  python -B - <<'PY_RELEASE'
import base64,hashlib,io,json,os,stat,zipfile
from pathlib import Path,PurePosixPath
expected='4eee283da478af9ae8ac616614976736a51d1efff160d2847e5126fbaf200ae5'
raw=base64.b64decode('',validate=True)
assert hashlib.sha256(raw).hexdigest()==expected,'PAYLOAD_SHA_MISMATCH'
root=Path('/root/autodl-tmp/minesim_dual_cachetiming_v1_release')
for p in [root]+list(root.parents):
    if p.is_symlink():raise RuntimeError('RELEASE_SYMLINK:'+str(p))
root.mkdir(exist_ok=True)
with zipfile.ZipFile(io.BytesIO(raw)) as z:
    names=z.namelist()
    assert len(names)==len(set(names)),'DUPLICATE_PAYLOAD_MEMBERS'
    manifest=json.loads(z.read('RELEASE_MANIFEST.json'))
    assert set(names)==set(manifest)|{'RELEASE_MANIFEST.json'},'PAYLOAD_MEMBER_SET'
    for n in names:
        p=PurePosixPath(n)
        assert not p.is_absolute() and '..' not in p.parts and '\\' not in n and str(p)==n,'UNSAFE_PAYLOAD_PATH'
        b=z.read(n)
        if n in manifest:
            assert manifest[n]=={'size':len(b),'sha256':hashlib.sha256(b).hexdigest()},'PAYLOAD_CONTENT_MISMATCH'
        target=root/n
        for q in [target]+list(target.parents):
            if q.is_symlink():raise RuntimeError('RELEASE_MEMBER_SYMLINK:'+str(q))
        if os.path.lexists(target):
            if not target.is_file() or target.read_bytes()!=b:raise RuntimeError('EXISTING_RELEASE_DIFFERS_NO_OVERWRITE:'+str(target))
        else:
            target.parent.mkdir(parents=True,exist_ok=True)
            with target.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())
print('RELEASE_VERIFIED='+expected,flush=True)
PY_RELEASE
  python -B - <<'PY_RESOURCE'
import importlib.util
from pathlib import Path
p=Path('/root/autodl-tmp/minesim_dual_cachetiming_v1_release/gate.py')
s=importlib.util.spec_from_file_location('cachetiming_resource_only',p)
m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
r=m.resources(Path('/root/autodl-tmp'))
print('RESOURCE_PREFLIGHT='+str(r),flush=True)
if not (r['effective_cpu']>=2 and r['memory_available_bytes']>=2*1024**3 and r['free_disk_bytes']>=1024**3):
    print('HOLD_RESOURCE_BEFORE_CLAIM：本次只写启动日志和发布文件，未创建实验lease/START，也未搜索。需要实际至少2有效CPU、2GiB可用内存、1GiB空闲磁盘。',flush=True)
    raise SystemExit(2)
PY_RESOURCE
  python -B -u /root/autodl-tmp/minesim_dual_cachetiming_v1_release/gate.py --authorize-cachetiming-once
) >>"$LOG" 2>&1
RC=$?
tail -n 24 "$LOG"
printf 'LAUNCHER_RC=%s\nLAUNCHER_LOG=%s\n' "$RC" "$LOG"
if [ "$RC" -ne 0 ]; then
  printf '%s\n' 'HOLD：保留结果、lease、pending和日志，不删除、不自动重跑。有BUNDLE上传对应ZIP，否则上传LAUNCHER_LOG。'
fi
exit "$RC"
